mapper.sql:
WHERE h.deleted_yn = 'N' AND l.deleted_yn = 'N'
AND h.business_date >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND h.business_date < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND h.due_date >= TO_DATE(#{dueStartDate}, 'YYYY-MM-DD')
AND h.due_date < TO_DATE(#{dueEndDate}, 'YYYY-MM-DD') + 1
AND h.progress_status = #{progressStatus}
AND UPPER(l.specification) LIKE '%' || UPPER(TRIM(#{specification})) || '%'
AND h.warehouse_id IN
#{warehouseId}
AND h.partner_id IN
#{partnerId}
AND l.item_id IN
#{itemId}
AND h.assignee_id IN
#{assigneeId}
AND l.unit_price >=#{minUnitPrice}
AND l.unit_price <=#{maxUnitPrice}
AND ( UPPER(h.sales_order_no) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR TO_CHAR(h.business_date, 'YYYY-MM-DD') LIKE '%' || TRIM(#{keyword}) || '%' OR TO_CHAR(h.business_date, 'YYYY/MM/DD') LIKE '%' || TRIM(#{keyword}) || '%' OR TO_CHAR(h.due_date, 'YYYY-MM-DD') LIKE '%' || TRIM(#{keyword}) || '%' OR TO_CHAR(h.due_date, 'YYYY/MM/DD') LIKE '%' || TRIM(#{keyword}) || '%' OR UPPER(i.item_code) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(l.item_name) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(l.specification) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(l.unit) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(h.partner_name) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(h.warehouse_name) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(h.assignee_name) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(h.note) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' OR UPPER(l.note) LIKE '%' || UPPER(TRIM(#{keyword})) || '%' )

mapper.select:
SELECT 
FROM SALES_ORDER h
JOIN SALES_ORDER_LINE l ON l.sales_order_id = h.sales_order_id
LEFT JOIN item i ON i.item_id = l.item_id




	AND l.quantity >= #{minQuantity}


	AND l.quantity <= #{maxQuantity}


	AND l.supply_amount >= #{minSupplyAmount}


	AND l.supply_amount <= #{maxSupplyAmount}


	AND l.vat_amount >= #{minVatAmount}


	AND l.vat_amount <= #{maxVatAmount}

ORDER BY h.business_date ASC, h.sales_order_id ASC, l.sales_order_line_id ASC
